Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_skipDeliveryRoleCheck">_skipDeliveryRoleCheck</param>
public void setDeliveryName(boolean _skipDeliveryRoleCheck)
{
    LogisticsPostalAddress   avaLocation = LogisticsPostalAddress::findRecId(this.DeliveryPostalAddress);

    next setDeliveryName(_skipDeliveryRoleCheck);

    this.DeliveryName = avaLocation.NDXLogisticsLocationName1;

    if(avaLocation.NDXLogisticsLocationName2)
    {
        this.DeliveryName += '\n' + avaLocation.NDXLogisticsLocationName2;
    }
    if(avaLocation.NDXLogisticsLocationName3)
    {
        this.DeliveryName += '\n' + avaLocation.NDXLogisticsLocationName3;
    }
}
